/*
 * A168877  Number of reduced words of length n in Coxeter group on 8
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^21 = I.
 * https://oeis.org/A168877
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 5, u32 n <= 11, u64 n <= 19, u128 n <= 19,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A168877: number of reduced words of length n in the Coxeter group
 * generated by 8 involutions with relations (S_i)^2 = 1 and (S_i S_j)^21 = 1
 * for i ≠ j.  This counts words over an 8‑letter alphabet with no two
 * consecutive equal letters and with no alternating run between any pair
 * of distinct letters that exceeds length 41 (i.e. no subword of the form
 * i,j,i,j,… of length 42).  The count for n < 42 equals 8·7^(n‑1).
 */

#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>

/* Maximum allowed alternating run length */
#define MAXALT 41U
/* Alphabet size */
#define ALPH   8U
/* Number of states: last letter (8) * second last (8) * run length (MAXALT-1) */
#define STATE_COUNT (ALPH * ALPH * (MAXALT-1))

/* Pre‑computed tables for state decoding */
static uint8_t *state_last;   /* last letter */
static uint8_t *state_sec;    /* second last letter */
static uint8_t *state_len;    /* current run length (2 .. MAXALT) */

/* DP buffers */
static seq_t *cur = NULL;    /* values for current length */
static seq_t *nxt = NULL;    /* values for next length */

/* Cache of sequence values */
static seq_t *cache = NULL;
static size_t cache_cap = 0;  /* allocated size of cache */

/* Current maximum n for which cache is computed */
static idx_t cache_n = 0;

/* Utility: compute linear index of a state */
static inline size_t state_index(int last, int sec, int len) {
    /* len is 2..MAXALT */
    return ((last * ALPH + sec) * (MAXALT - 1)) + (len - 2);
}

/* Initialise tables, DP buffers and cache */
static void seq_init(void) {
    /* Allocate and fill decoding tables */
    state_last = (uint8_t*)malloc(STATE_COUNT * sizeof(uint8_t));
    state_sec  = (uint8_t*)malloc(STATE_COUNT * sizeof(uint8_t));
    state_len  = (uint8_t*)malloc(STATE_COUNT * sizeof(uint8_t));
    if (!state_last || !state_sec || !state_len) abort();

    for (int last = 0; last < ALPH; ++last) {
        for (int sec = 0; sec < ALPH; ++sec) {
            for (int len = 2; len <= (int)MAXALT; ++len) {
                size_t idx = state_index(last, sec, len);
                state_last[idx] = (uint8_t)last;
                state_sec[idx]  = (uint8_t)sec;
                state_len[idx]  = (uint8_t)len;
            }
        }
    }

    /* Allocate DP arrays */
    cur = (seq_t*)calloc(STATE_COUNT, sizeof(seq_t));
    nxt = (seq_t*)calloc(STATE_COUNT, sizeof(seq_t));
    if (!cur || !nxt) abort();

    /* Allocate cache (at least for indices 0..2) */
    cache_cap = 2;
    cache = (seq_t*)calloc(cache_cap + 1, sizeof(seq_t));
    if (!cache) abort();
    cache[0] = (seq_t)1;      /* a(0) = 1 */
    cache[1] = (seq_t)8;      /* a(1) = 8 */

    /* Initialise DP for length 2 */
    for (int a = 0; a < ALPH; ++a) {
        for (int b = 0; b < ALPH; ++b) {
            if (b == a) continue;
            size_t idx = state_index(b, a, 2);
            cur[idx] = (seq_t)1;
        }
    }
    /* Compute a(2) */
    seq_t total = (seq_t)0;
    for (size_t i = 0; i < STATE_COUNT; ++i) total += cur[i];
    cache[2] = total;
    cache_n = 2;
}

/* Extend cache and DP to compute values up to n */
static void ensure_cache_size(idx_t n) {
    if (n <= cache_n) return;
    /* Expand DP buffers if necessary (state count fixed) */
    if (!cur || !nxt) seq_init();

    for (idx_t len = cache_n + 1; len <= n; ++len) {
        /* Zero next buffer */
        memset(nxt, 0, STATE_COUNT * sizeof(seq_t));

        /* Transition from current states to next */
        for (size_t idx = 0; idx < STATE_COUNT; ++idx) {
            seq_t val = cur[idx];
            if (!val) continue;
            int last = state_last[idx];
            int sec  = state_sec[idx];
            int run  = state_len[idx];  /* 2 .. MAXALT */

            /* Try all possible next letters (must differ from last) */
            for (int nxt_l = 0; nxt_l < ALPH; ++nxt_l) {
                if (nxt_l == last) continue;           /* no consecutive equal letters */
                int new_len = (nxt_l == sec) ? run + 1 : 2;
                if (new_len > (int)MAXALT) continue;   /* would exceed max allowed */
                int new_last = nxt_l;
                int new_sec  = last;
                size_t nxt_idx = state_index(new_last, new_sec, new_len);
                nxt[nxt_idx] += val;
            }
        }

        /* Sum to get a(len) and store in cache */
        seq_t total = (seq_t)0;
        for (size_t i = 0; i < STATE_COUNT; ++i) total += nxt[i];
        if (len > cache_cap) {
            cache_cap = len;
            cache = (seq_t*)realloc(cache, (cache_cap + 1) * sizeof(seq_t));
            if (!cache) abort();
        }
        cache[len] = total;

        /* Swap cur and nxt for next iteration */
        seq_t *tmp = cur;
        cur = nxt;
        nxt = tmp;
    }

    cache_n = n;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)1;        /* a(0) */
    /* Lazy initialization */
    if (!cur) seq_init();

    if (n <= cache_n) return cache[n];

    ensure_cache_size(n);
    return cache[n];
}
